class Solution {
public:
    bool isPrintable(vector<vector<int>>& targetGrid) {
        int m = targetGrid.size(), n = targetGrid[0].size();
        unordered_set<int> colors;
        vector<int> min_r(61, 100), max_r(61, -1), min_c(61, 100), max_c(61, -1);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                int col = targetGrid[r][c];
                colors.insert(col);
                min_r[col] = min(min_r[col], r);
                max_r[col] = max(max_r[col], r);
                min_c[col] = min(min_c[col], c);
                max_c[col] = max(max_c[col], c);
            }
        }
        vector<unordered_set<int>> adj(61);
        vector<int> in_degree(61, 0);
        for (int col : colors) {
            for (int r = min_r[col]; r <= max_r[col]; ++r) {
                for (int c = min_c[col]; c <= max_c[col]; ++c) {
                    int other = targetGrid[r][c];
                    if (other != col && adj[col].find(other) == adj[col].end()) {
                        adj[col].insert(other);
                    }
                }
            }
        }
        for (int col : colors) {
            for (int v : adj[col]) {
                in_degree[v]++;
            }
        }
        queue<int> q;
        for (int col : colors) {
            if (in_degree[col] == 0) q.push(col);
        }
        int count = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            count++;
            for (int v : adj[u]) {
                if (--in_degree[v] == 0) q.push(v);
            }
        }
        return count == (int)colors.size();
    }
};

import java.util.*;

class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length, n = targetGrid[0].length;
        Set<Integer> colors = new HashSet<>();
        int[] minR = new int[61], maxR = new int[61], minC = new int[61], maxC = new int[61];
        Arrays.fill(minR, 100); Arrays.fill(maxR, -1);
        Arrays.fill(minC, 100); Arrays.fill(maxC, -1);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                int col = targetGrid[r][c];
                colors.add(col);
                minR[col] = Math.min(minR[col], r);
                maxR[col] = Math.max(maxR[col], r);
                minC[col] = Math.min(minC[col], c);
                maxC[col] = Math.max(maxC[col], c);
            }
        }
        List<Set<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= 60; ++i) adj.add(new HashSet<>());
        int[] inDegree = new int[61];
        for (int col : colors) {
            for (int r = minR[col]; r <= maxR[col]; ++r) {
                for (int c = minC[col]; c <= maxC[col]; ++c) {
                    int other = targetGrid[r][c];
                    if (other != col && !adj.get(col).contains(other)) {
                        adj.get(col).add(other);
                    }
                }
            }
        }
        for (int col : colors) {
            for (int v : adj.get(col)) {
                inDegree[v]++;
            }
        }
        Queue<Integer> q = new LinkedList<>();
        for (int col : colors) {
            if (inDegree[col] == 0) q.offer(col);
        }
        int count = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            count++;
            for (int v : adj.get(u)) {
                if (--inDegree[v] == 0) q.offer(v);
            }
        }
        return count == colors.size();
    }
}

