var isPrintable = function(targetGrid) {
    const m = targetGrid.length, n = targetGrid[0].length;
    const colors = new Set();
    const minR = Array(61).fill(100), maxR = Array(61).fill(-1);
    const minC = Array(61).fill(100), maxC = Array(61).fill(-1);
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            const col = targetGrid[r][c];
            colors.add(col);
            minR[col] = Math.min(minR[col], r);
            maxR[col] = Math.max(maxR[col], r);
            minC[col] = Math.min(minC[col], c);
            maxC[col] = Math.max(maxC[col], c);
        }
    }
    const adj = Array.from({ length: 61 }, () => new Set());
    const inDegree = Array(61).fill(0);
    for (const col of colors) {
        for (let r = minR[col]; r <= maxR[col]; ++r) {
            for (let c = minC[col]; c <= maxC[col]; ++c) {
                const other = targetGrid[r][c];
                if (other !== col && !adj[col].has(other)) {
                    adj[col].add(other);
                }
            }
        }
    }
    for (const col of colors) {
        for (const v of adj[col]) {
            inDegree[v]++;
        }
    }
    const q = [];
    for (const col of colors) {
        if (inDegree[col] === 0) q.push(col);
    }
    let count = 0;
    while (q.length > 0) {
        const u = q.shift();
        count++;
        for (const v of adj[u]) {
            if (--inDegree[v] === 0) q.push(v);
        }
    }
    return count === colors.size;
};
